18	
19	    /** Fixed public-holiday calendar; these dates are never business days. */
20	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
21	            LocalDate.of(2026, 1, 1),
22	            LocalDate.of(2026, 1, 26),
23	            LocalDate.of(2026, 4, 25),
24	            LocalDate.of(2026, 12, 25),
25	            LocalDate.of(2026, 12, 28));
26	
27	    private RegistrationDates() {
28	    }
29	
30	    /** The number of existing owners whose stored registration date equals {@code day}. */
31	    static long countRegisteredOn(LocalDate day, OwnerRepository ownerRepository) {
32	        return ownerRepository.findAll().stream()
33	                .filter(existing -> day != null && day.equals(existing.getRegistrationDate()))
34	                .count();
35	    }
36	
37	    /**
38	     * The effective registration date: the supplied date, or the server's current date when none
39	     * was supplied, rolled forward off a weekend to the next business day.
40	     */
41	    static LocalDate effective(LocalDate supplied) {
42	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
43	    }
44	
45	    /**
46	     * Roll a weekend or public holiday forward to the next non-holiday business day; any other day
47	     * is returned unchanged.
48	     */
49	    static LocalDate toBusinessDay(LocalDate date) {
50	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
51	            date = date.plusDays(1);
52	        }
53	        return date;
54	    }
55	
56	    private static boolean isWeekend(LocalDate date) {
57	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
58	    }
59	}
