311	     * The number of owners in this owner's household (owners sharing the same
312	     * {@link #householdId}), derived at response time and not persisted.
313	     */
314	    public Integer getHouseholdSize() {
315	        return this.householdSize;
316	    }
317	
318	    public void setHouseholdSize(Integer householdSize) {
319	        this.householdSize = householdSize;
320	    }
