322	    /**
323	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
324	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
325	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds 365 days
326	     * (measured from the {@link #registrationDate}).
327	     */
328	    public Integer getMembershipPoints() {
329	        int points = 0;
330	        if (this.email != null && !this.email.isEmpty()) {
331	            points += 2;
332	        }
333	        if (this.namesakeCount != null && this.namesakeCount == 0) {
334	            points += 1;
335	        }
336	        if (this.householdSize != null && this.householdSize >= 3) {
337	            points += 2;
338	        }
339	        if (getTenureDays() > 365) {
340	            points += 3;
341	        }
342	        return points;
