345	    /**
346	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
347	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
348	     * 6 or more points.
349	     */
350	    public Integer getMembershipLevel() {
351	        int points = getMembershipPoints();
352	        if (points <= 1) {
353	            return 1;
354	        }
355	        if (points <= 3) {
356	            return 2;
357	        }
358	        if (points <= 5) {
359	            return 3;
360	        }
361	        return 4;
