364	    /**
365	     * The owner's tenure in whole days, measured from the {@link #registrationDate} to today; zero
366	     * when the registration date is absent or in the future.
367	     */
368	    private long getTenureDays() {
369	        if (this.registrationDate == null) {
370	            return 0;
371	        }
372	        long days = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
373	        return Math.max(days, 0);
