376	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
377	    private static final Map<String, String> CITY_REGION = Map.of(
378	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
379	
380	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
381	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
382	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
383	
384	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
385	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
386	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
387	
388	    /**
389	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
390	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
391	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
392	     * for {@code null} before range-checking the postcode.
393	     */
394	    public static String regionOf(String city) {
395	        return CITY_REGION.get(city);
396	    }
