398	    /**
399	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
400	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
401	     * absent, not a 4-digit number, or in no known range.
402	     */
403	    public static String regionOfPostcode(String postcode) {
404	        if (postcode == null || postcode.isEmpty()) {
405	            return null;
406	        }
407	        int value;
408	        try {
409	            value = Integer.parseInt(postcode);
410	        } catch (NumberFormatException ex) {
411	            return null;
412	        }
413	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
414	            int[] range = entry.getValue();
415	            if (value >= range[0] && value <= range[1]) {
416	                return entry.getKey();
417	            }
418	        }
419	        return null;
420	    }
