422	    /**
423	     * The owner's region, derived at response time from the {@code REGION} prefix of the
424	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
425	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
426	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
427	     * customer code.
428	     */
429	    public String getLocality() {
430	        if (this.customerCode == null) {
431	            return "UNKNOWN";
432	        }
433	        int dash = this.customerCode.indexOf('-');
434	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
435	    }
436	
437	    /**
438	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
439	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
440	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null}
441	     * when the region is not in the table. Not persisted.
442	     */
443	    public String getTimezone() {
444	        return REGION_TIMEZONE.get(getLocality());
445	    }
