447	    /**
448	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
449	     * email is present, otherwise {@code PHONE}. Not persisted.
450	     */
451	    public String getContactPreference() {
452	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
453	    }
454	
455	    /**
456	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
457	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
458	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
459	     * digit from the right, subtracting 9 from any result over 9, and taking
460	     * {@code (10 - sum % 10) % 10}. Not persisted.
461	     */
462	    public Integer getCheckDigit() {
463	        if (this.customerCode == null) {
464	            return null;
465	        }
466	        int sum = 0;
467	        boolean dbl = true;
468	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
469	            char c = this.customerCode.charAt(i);
470	            if (c < '0' || c > '9') {
471	                continue;
472	            }
473	            int d = c - '0';
474	            if (dbl) {
475	                d *= 2;
476	                if (d > 9) {
477	                    d -= 9;
478	                }
479	            }
480	            sum += d;
481	            dbl = !dbl;
482	        }
483	        return (10 - (sum % 10)) % 10;
484	    }
485	
486	    /**
487	     * A display-only derived string composing the owner's canonical contact and household values:
488	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
489	     * canonical E.164 form and the email lower-cased; an absent email or householdId contributes an
490	     * empty segment. Derived at response time and exposed as a read-only response field only — it
491	     * drives no check. Duplicate detection is purely household-based (see
492	     * {@code CheckOwnerHouseholdUnique}, which compares {@link #getHouseholdId() householdId}); this
493	     * key is not consulted. Not persisted.
494	     */
495	    public String getIdentityKey() {
496	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
497	    }
498	
499	    private static String keyPart(String value) {
500	        return value == null ? "" : value;
501	    }
502	
503	    /**
504	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
505	     * national digits (everything after the country code) grouped in threes and space-separated —
506	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
507	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
508	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
509	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
510	     */
511	    public String getTelephoneDisplay() {
512	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
513	            return null;
514	        }
515	        String digits = this.telephone.substring(1);
516	        int countryCodeLength;
517	        if (digits.startsWith("61")) {
518	            countryCodeLength = 2;
519	        }
520	        else if (digits.startsWith("1")) {
521	            countryCodeLength = 1;
522	        }
523	        else {
524	            countryCodeLength = 2;
525	        }
526	        String countryCode = digits.substring(0, countryCodeLength);
527	        String national = digits.substring(countryCodeLength);
528	        StringBuilder display = new StringBuilder("+").append(countryCode);
529	        for (int i = 0; i < national.length(); i += 3) {
530	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
531	        }
532	        return display.toString();
533	    }
